#include "fire_kernel.h"
#include "gdextension_interface.h"
#include "godot_abi.h" // Generated by build.ps1 from the exact engine's API dump.

#include <cstdint>

namespace {

constexpr auto packed_type = GDEXTENSION_VARIANT_TYPE_PACKED_FLOAT64_ARRAY;
GDExtensionClassLibraryPtr library;
GDExtensionInterfaceStringNameNewWithLatin1Chars make_name;
GDExtensionInterfaceClassdbRegisterExtensionClass6 register_class;
GDExtensionInterfaceClassdbUnregisterExtensionClass unregister_class;
GDExtensionInterfaceClassdbRegisterExtensionClassMethod register_method;
GDExtensionInterfaceVariantGetType variant_type;
GDExtensionInterfaceVariantDestroy variant_destroy;
GDExtensionInterfacePackedFloat64ArrayOperatorIndex write_at;
GDExtensionInterfacePackedFloat64ArrayOperatorIndexConst read_at;
GDExtensionPtrBuiltInMethod array_size, array_resize;
GDExtensionPtrConstructor array_new;
GDExtensionPtrDestructor array_destroy, name_destroy;
GDExtensionPtrConstructor string_new;
GDExtensionPtrDestructor string_destroy;
GDExtensionVariantFromTypeConstructorFunc to_variant;
GDExtensionTypeFromVariantConstructorFunc from_variant, read_double;

struct Name {
    alignas(8) char storage[abi::name_size];
    explicit Name(const char *text) { make_name(storage, text, false); }
    ~Name() { name_destroy(storage); }
};

struct PackedArray {
    alignas(8) char storage[abi::array_size];
    PackedArray() { array_new(storage, nullptr); }
    explicit PackedArray(GDExtensionConstVariantPtr value) {
        from_variant(storage, const_cast<GDExtensionVariantPtr>(value));
    }
    ~PackedArray() { array_destroy(storage); }
    std::size_t size() {
        int64_t length = 0;
        array_size(storage, nullptr, &length, 0);
        return static_cast<std::size_t>(length);
    }
    bool resize(int64_t count) {
        const GDExtensionConstTypePtr args[] = {&count};
        int64_t error = 0;
        array_resize(storage, args, &error, 1);
        return error == 0;
    }
};

enum Operation : uintptr_t { exchange, fit, boundary, support_floors, candidate_pairs, build_network };

int argument_count(Operation operation) {
    if (operation == fit) return 4;
    if (operation == candidate_pairs) return 1;
    if (operation == build_network) return 3;
    return 2;
}

void call(void *userdata, GDExtensionClassInstancePtr, const GDExtensionConstVariantPtr *args,
          GDExtensionInt count, GDExtensionVariantPtr output, GDExtensionCallError *error) {
    const auto operation = static_cast<Operation>(reinterpret_cast<uintptr_t>(userdata));
    const int expected = argument_count(operation);
    if (count != expected) {
        error->error = count < expected ? GDEXTENSION_CALL_ERROR_TOO_FEW_ARGUMENTS : GDEXTENSION_CALL_ERROR_TOO_MANY_ARGUMENTS;
        error->expected = expected;
        return;
    }
    for (int i = 0; i < expected; ++i) {
        const auto type = operation == fit && i > 0 ? GDEXTENSION_VARIANT_TYPE_FLOAT : packed_type;
        if (variant_type(args[i]) != type) {
            error->error = GDEXTENSION_CALL_ERROR_INVALID_ARGUMENT;
            error->argument = i;
            error->expected = type;
            return;
        }
    }
    PackedArray result;
    PackedArray values(args[0]);
    if (operation == fit) {
        double scalars[3];
        for (int i = 0; i < 3; ++i) {
            read_double(&scalars[i], const_cast<GDExtensionVariantPtr>(args[i + 1]));
        }
        const auto length = values.size();
        if (length >= 2 && result.resize(2) &&
            !fire::fit(read_at(values.storage, 0), length, scalars[0], scalars[1], scalars[2], write_at(result.storage, 0))) {
            result.resize(0);
        }
    } else if (operation == candidate_pairs) {
        const auto values_count = values.size();
        const auto nodes = values_count / 6;
        if (nodes >= 2 && nodes <= 1024 && result.resize(nodes * (nodes - 1))) {
            std::size_t actual = 0;
            if (!fire::candidate_pairs(read_at(values.storage, 0), values_count, write_at(result.storage, 0), actual)) {
                actual = 0;
            }
            result.resize(actual);
        }
    } else if (operation == build_network) {
        PackedArray blockers(args[1]), pairs(args[2]);
        const auto length = values.size(), blocker_length = blockers.size(), pair_length = pairs.size();
        const auto nodes = length / fire::geometry_width;
        if (nodes && nodes <= 1024 && blocker_length <= 1024 * fire::occluder_width &&
                pair_length <= nodes * (nodes - 1) && result.resize(1 + 2 * nodes + pair_length / 2 * fire::link_width)) {
            std::size_t actual = 0;
            if (!fire::build_network(read_at(values.storage, 0), length,
                    blocker_length ? read_at(blockers.storage, 0) : nullptr, blocker_length,
                    pair_length ? read_at(pairs.storage, 0) : nullptr, pair_length,
                    write_at(result.storage, 0), actual)) {
                actual = 0;
            }
            result.resize(actual);
        }
    } else {
        PackedArray links(args[1]);
        const auto node_values = values.size();
        const auto link_values = links.size();
        const auto output_size = operation == support_floors ? node_values / 6 * 2
            : fire::exchange_output_size(node_values, link_values);
        if (operation == support_floors && output_size && result.resize(output_size)) {
            if (!fire::support_floors(read_at(values.storage, 0), node_values,
                                     link_values ? read_at(links.storage, 0) : nullptr, link_values, write_at(result.storage, 0))) {
                result.resize(0);
            }
        } else if (operation != support_floors && output_size && result.resize(output_size) && operation == exchange) {
            if (!fire::exchange(node_values ? read_at(values.storage, 0) : nullptr, node_values,
                                link_values ? read_at(links.storage, 0) : nullptr, link_values, write_at(result.storage, 0))) {
                result.resize(0);
            }
        }
    }
    variant_destroy(output);
    to_variant(output, result.storage);
    error->error = GDEXTENSION_CALL_OK;
}

void add_method(const Name &klass, const char *method_name, Operation operation) {
    Name name(method_name), empty(""), nodes("nodes"), links("links");
    Name samples("samples"), desired("desired"), balance("balance"), span("span");
    Name blockers("blockers"), pairs("pairs");
    alignas(8) char hint[abi::string_size];
    string_new(hint, nullptr);
    auto property = [&](Name &label, GDExtensionVariantType type) {
        return GDExtensionPropertyInfo{type, label.storage, empty.storage, 0, hint, 6};
    };
    auto result = property(empty, packed_type);
    GDExtensionPropertyInfo exchange_args[] = {property(nodes, packed_type), property(links, packed_type)};
    GDExtensionPropertyInfo network_args[] = {property(nodes, packed_type), property(blockers, packed_type), property(pairs, packed_type)};
    GDExtensionPropertyInfo fit_args[] = {
        property(samples, packed_type), property(desired, GDEXTENSION_VARIANT_TYPE_FLOAT),
        property(balance, GDEXTENSION_VARIANT_TYPE_FLOAT), property(span, GDEXTENSION_VARIANT_TYPE_FLOAT)
    };
    GDExtensionClassMethodArgumentMetadata metadata[4] = {};
    GDExtensionClassMethodInfo method{};
    method.name = name.storage;
    method.method_userdata = reinterpret_cast<void *>(static_cast<uintptr_t>(operation));
    method.call_func = call;
    method.method_flags = GDEXTENSION_METHOD_FLAG_NORMAL | GDEXTENSION_METHOD_FLAG_STATIC;
    method.has_return_value = true;
    method.return_value_info = &result;
    method.argument_count = argument_count(operation);
    method.arguments_info = operation == fit ? fit_args : (operation == build_network ? network_args : exchange_args);
    method.arguments_metadata = metadata;
    register_method(library, klass.storage, &method);
    string_destroy(hint);
}

void initialize(void *, GDExtensionInitializationLevel level) {
    if (level != GDEXTENSION_INITIALIZATION_SCENE) {
        return;
    }
    Name klass("FiretenderKernel"), parent("Object");
    GDExtensionClassCreationInfo6 info{};
    info.is_abstract = true;
    info.is_exposed = true;
    info.free_instance_func = [](void *, GDExtensionClassInstancePtr) {};
    register_class(library, klass.storage, parent.storage, &info);
    add_method(klass, "exchange", exchange);
    add_method(klass, "fit", fit);
    add_method(klass, "boundary", boundary);
    add_method(klass, "support_floors", support_floors);
    add_method(klass, "candidate_pairs", candidate_pairs);
    add_method(klass, "build_network", build_network);
}

void deinitialize(void *, GDExtensionInitializationLevel level) {
    if (level == GDEXTENSION_INITIALIZATION_SCENE) {
        Name klass("FiretenderKernel");
        unregister_class(library, klass.storage);
    }
}

} // namespace

extern "C" __declspec(dllexport) GDExtensionBool firetender_kernel_init(
    GDExtensionInterfaceGetProcAddress get, GDExtensionClassLibraryPtr handle, GDExtensionInitialization *out) {
#define LOAD(target, name) \
    target = reinterpret_cast<decltype(target)>(get(name)); \
    if (!target) return false
    LOAD(make_name, "string_name_new_with_latin1_chars");
    LOAD(register_class, "classdb_register_extension_class6");
    LOAD(unregister_class, "classdb_unregister_extension_class");
    LOAD(register_method, "classdb_register_extension_class_method");
    LOAD(variant_type, "variant_get_type");
    LOAD(variant_destroy, "variant_destroy");
    LOAD(write_at, "packed_float64_array_operator_index");
    LOAD(read_at, "packed_float64_array_operator_index_const");
    GDExtensionInterfaceGetVariantFromTypeConstructor convert_to;
    GDExtensionInterfaceGetVariantToTypeConstructor convert_from;
    GDExtensionInterfaceVariantGetPtrBuiltinMethod builtin_method;
    GDExtensionInterfaceVariantGetPtrConstructor constructor;
    GDExtensionInterfaceVariantGetPtrDestructor destructor;
    LOAD(convert_to, "get_variant_from_type_constructor");
    LOAD(convert_from, "get_variant_to_type_constructor");
    LOAD(builtin_method, "variant_get_ptr_builtin_method");
    LOAD(constructor, "variant_get_ptr_constructor");
    LOAD(destructor, "variant_get_ptr_destructor");
#undef LOAD
    library = handle;
    name_destroy = destructor(GDEXTENSION_VARIANT_TYPE_STRING_NAME);
    Name size("size"), resize("resize");
    array_size = builtin_method(packed_type, size.storage, abi::size_hash);
    array_resize = builtin_method(packed_type, resize.storage, abi::resize_hash);
    if (!array_size || !array_resize) {
        return false;
    }
    array_new = constructor(packed_type, 0);
    array_destroy = destructor(packed_type);
    string_new = constructor(GDEXTENSION_VARIANT_TYPE_STRING, 0);
    string_destroy = destructor(GDEXTENSION_VARIANT_TYPE_STRING);
    to_variant = convert_to(packed_type);
    from_variant = convert_from(packed_type);
    read_double = convert_from(GDEXTENSION_VARIANT_TYPE_FLOAT);
    out->minimum_initialization_level = GDEXTENSION_INITIALIZATION_SCENE;
    out->initialize = initialize;
    out->deinitialize = deinitialize;
    return true;
}
